def evidence_score(evidence):
    components={"out_of_sample_performance":max(0,min(100,50+float(evidence.get("oos_return",0))*5)),"walk_forward_stability":float(evidence.get("walk_forward_stability",0)),"parameter_stability":float(evidence.get("parameter_stability",0)),"robustness_to_costs":float(evidence.get("robustness_score",0)),"drawdown_control":max(0,100-float(evidence.get("max_drawdown",100))*3),"trade_count_quality":min(100,float(evidence.get("trade_count",0))*2),"symbol_coverage":min(100,float(evidence.get("symbol_coverage",0))*10),"regime_consistency":float(evidence.get("regime_score",0)),"cost_sensitivity":float(evidence.get("cost_score",0)),"false_discovery_risk":{"low":90,"medium":50,"high":10}.get(evidence.get("false_discovery_risk","high"),10),"paper_trading_alignment_if_available":float(evidence.get("paper_alignment",0))}
    weights={"out_of_sample_performance":.18,"walk_forward_stability":.15,"parameter_stability":.12,"robustness_to_costs":.12,"drawdown_control":.1,"trade_count_quality":.08,"symbol_coverage":.08,"regime_consistency":.05,"cost_sensitivity":.05,"false_discovery_risk":.05,"paper_trading_alignment_if_available":.02};score=sum(components[k]*weights[k] for k in components);penalties=[]
    if evidence.get("oos_return",0)<=0:score-=20;penalties.append("Out-of-sample return is not positive")
    if evidence.get("parameter_stability",0)<40:score-=10;penalties.append("Parameter stability is weak")
    return {"evidence_score":max(0,round(score,2)),"components":components,"penalties":penalties}
